import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    r = int(data[0])
    lines = []
    for i in range(1, r + 1):
        if i == 1:
            line = "*"
        elif i == r:
            line = " ".join(["*"] * i)
        else:
            line = "*" + " " * (2 * i - 3) + "*"
        lines.append(line)
    sys.stdout.write("\n".join(lines) + ("\n" if lines else ""))

main()
